theorem isArithmeticSL_iff_isTakeuchiConj {A B : SL(2, ℝ)}
    (hcomm : tr (A * B * A⁻¹ * B⁻¹) = -2) :
    IsArithmeticSL (Subgroup.closure {A, B}) ↔ IsTakeuchiConj A B

theorem not_admitsCore_of_isTakeuchiConj {A B : SL(2, ℝ)}
    (hcomm : tr (A * B * A⁻¹ * B⁻¹) = -2) (h : IsTakeuchiConj A B) :
    ¬ AdmitsCore (Subgroup.closure {A, B})

theorem not_admitsCore_iff_isTakeuchiConj (hM : MargulisOneInfty) {A B : SL(2, ℝ)}
    (hcomm : tr (A * B * A⁻¹ * B⁻¹) = -2) (hA : tr A ≠ 0) :
    ¬ AdmitsCore (Subgroup.closure {A, B}) ↔ IsTakeuchiConj A B

theorem admitsCore_iff_not_isArithmeticSL (hM : MargulisOneInfty) {A B : SL(2, ℝ)}
    (hcomm : tr (A * B * A⁻¹ * B⁻¹) = -2) (hA : tr A ≠ 0) :
    AdmitsCore (Subgroup.closure {A, B}) ↔ ¬ IsArithmeticSL (Subgroup.closure {A, B})

theorem Complex.exists_ne_forall_aeval_eq_zero_iff {z : ℂ}
    (hz : z ∉ Set.range ((↑) : ℚ → ℂ)) :
    ∃ y : ℂ, y ≠ z ∧ ∀ p : ℚ[X], aeval z p = 0 ↔ aeval y p = 0

lemma smul_eq_mob_tri (g : GL (Fin 2) k) {t : OnePoint k × OnePoint k × OnePoint k}
    (ht : Distinct3 t) (x : OnePoint k) :
    g • x = mob (tri (smul3 g t)) (mob (tri t).adjugate x)

lemma rel_smul3 (g : GL (Fin 2) k) {t : OnePoint k × OnePoint k × OnePoint k}
    (ht : Distinct3 t) (t' : OnePoint k × OnePoint k × OnePoint k) :
    rel (smul3 g t) (smul3 g t') = rel t t'

lemma continuousAt_mob_param {T : Type*} [TopologicalSpace T] {M : T → Matrix (Fin 2) (Fin 2) k}
    {t₀ : T} (hM : ContinuousAt M t₀) (hdet : (M t₀).det ≠ 0) (x₀ : OnePoint k) :
    ContinuousAt (fun p : T × OnePoint k ↦ mob (M p.1) p.2) (t₀, x₀)

theorem commensurator_dense {Γ : Subgroup SL(2, ℝ)} (hΓ : HasFiniteCovolume Γ) {A B : SL(2, ℝ)}
    (hA : A ∈ Γ) (hB : B ∈ Γ) (hx : 4 < tr A ^ 2) (hc : tr (A * B * A⁻¹ * B⁻¹) ≠ 2)
    (hy : tr B ≠ 0) (hno : ¬ AdmitsCore Γ) : Dense (commensurator Γ : Set SL(2, ℝ))

lemma exists_ball_disjoint (Δ : Subgroup SL(2, ℝ)) [DiscreteTopology Δ] {z₀ : ℍ}
    (hz₀ : ∀ g ∈ Δ, g ≠ 1 → g ≠ -1 → g • z₀ ≠ z₀) :
    ∃ r > 0, ∀ g ∈ Δ, (g • Metric.ball z₀ r ∩ Metric.ball z₀ r).Nonempty → g = 1 ∨ g = -1

lemma tendsto_of_entries {g : ℕ → SL(2, ℝ)} {M : SL(2, ℝ)}
    (h : ∀ i j, Tendsto (fun n ↦ (g n : Matrix (Fin 2) (Fin 2) ℝ) i j) atTop (𝓝 (M i j))) :
    Tendsto g atTop (𝓝 M)

theorem exists_strip_cover_normal (hx : 0 < x) (hy : 0 < y) (h1 : x < y + z) (h2 : y < x + z)
    (h3 : z < x + y) : ∃ η > 0, ∀ w : ℍ, ∃ γ ∈ Subgroup.closure {nA hz hrel, nB hz hrel},
      γ • w ∈ {z : ℍ | z.re ∈ Icc (-1) (-1 + 2) ∧ η ≤ z.im}

theorem canLift27_group_iff (hM : MargulisDenseOneInfty) {A B : SL(2, ℝ)}
    (hcomm : tr (A * B * A⁻¹ * B⁻¹) = -2) (hA : tr A ≠ 0) :
    ¬ AdmitsCore (Subgroup.closure {A, B}) ↔ IsTakeuchiConj A B

lemma smul_coe_bdry (g : SL(2, ℝ)) (k : ℝ) :
    g • (k : OnePoint ℝ) =
      if g 1 0 * k + g 1 1 = 0 then ∞ else ↑((g 0 0 * k + g 0 1) / (g 1 0 * k + g 1 1))

lemma liftE_mul_left {γ : SL(2, ℝ)}
    (hγ : (fun p : OnePoint ℝ × OnePoint ℝ ↦ (γ • p.1, γ • p.2)) ⁻¹' E = E) (g : SL(2, ℝ)) :
    liftE E (γ * g) = liftE E g

lemma bdry_prod_apply {T : Set (OnePoint ℝ × OnePoint ℝ)} (hT : MeasurableSet T) :
    (bdry.prod bdry) T =
      volume {q : ℝ × ℝ | (((q.1 : ℝ) : OnePoint ℝ), ((q.2 : ℝ) : OnePoint ℝ)) ∈ T}

theorem lintegral_pou_mul_right [Countable Γ] (hF : MeasurableSet F) {Ψ : SL(2, ℝ) → ℝ≥0∞}
    (hΨ : Measurable Ψ) (hinv : ∀ γ ∈ Γ, ∀ g, Ψ (γ * g) = Ψ g) {h : SL(2, ℝ)}
    (hR : ∀ G : SL(2, ℝ) → ℝ≥0∞, Measurable G →
      ∫⁻ g, G (g * h) ∂hopfMeasure = ∫⁻ g, G g ∂hopfMeasure) :
    ∫⁻ g, pou Γ F g * Ψ (g * h) ∂hopfMeasure = ∫⁻ g, pou Γ F g * Ψ g ∂hopfMeasure

lemma rep_unique (h : IsRatMul g) {c : ℝ} (hc : c ≠ 0) {R : Matrix (Fin 2) (Fin 2) ℚ}
    (hR : (g : Matrix (Fin 2) (Fin 2) ℝ) = c • R.map ((↑) : ℚ → ℝ)) :
    ∃ μ : ℚ, μ ≠ 0 ∧ R = μ • h.rep

lemma mem_or_neg_mem_of_signs {A B A'' B'' : SL(2, ℝ)} (hA : A'' ∈ ({A, -A} : Set SL(2, ℝ)))
    (hB : B'' ∈ ({B, -B} : Set SL(2, ℝ))) {γ : SL(2, ℝ)} (hγ : γ ∈ Subgroup.closure {A, B}) :
    γ ∈ Subgroup.closure {A'', B''} ∨ -γ ∈ Subgroup.closure {A'', B''}

lemma two_point_diag [MeasurableEq Y] {μ : Measure Y}
    [IsProbabilityMeasure μ] {a b : Y} (hab : a ≠ b) (h : μ ({a, b}ᶜ) = 0) :
    (μ.prod μ) (diagonal Y) = μ {a} ^ 2 + μ {b} ^ 2

lemma two_point_heavy [MeasurableEq Y] {μ : Measure Y}
    [IsProbabilityMeasure μ] {a b : Y} (h : μ ({a, b}ᶜ) = 0)
    (hφ : 1 / 2 < (μ.prod μ) (diagonal Y)) : ∃ z, 1 / 2 < μ {z}

lemma two_point_pair [MeasurableEq Y] {μ : Measure Y}
    [IsProbabilityMeasure μ] {a b : Y} (h : μ ({a, b}ᶜ) = 0)
    (hφ : (μ.prod μ) (diagonal Y) ≤ 1 / 2) : a ≠ b ∧ μ {a} = 1 / 2 ∧ μ {b} = 1 / 2

lemma exists_tendsto_integral_of_tendsto {θ : ℕ → ProbabilityMeasure Y} {ν : ProbabilityMeasure Y}
    (h : Tendsto θ atTop (𝓝 ν)) (f : Y →ᵇ ℝ) :
