lemma TailWeights.tendsto_lim [T2Space (ProbabilityMeasure Y)] (W : TailWeights) {G : Type*}
    {Θ : ℕ → G → ProbabilityMeasure Y} (ν₀ : ProbabilityMeasure Y) {g : G}
    (hg : g ∈ W.convSet Θ) :
