lemma pow_mul_sub_smul_one_eq {M : Matrix (Fin 2) (Fin 2) k} {μ₁ μ₂ : k}
    (hs : μ₁ + μ₂ = M.trace) (hp : μ₁ * μ₂ = M.det) (n : ℕ) :
    M ^ n * (M - μ₂ • 1) = μ₁ ^ n • (M - μ₂ • 1)

lemma sub_smul_pow_eq {M : Matrix (Fin 2) (Fin 2) k} {μ₁ μ₂ : k}
    (hs : μ₁ + μ₂ = M.trace) (hp : μ₁ * μ₂ = M.det) (n : ℕ) :
    (μ₁ - μ₂) • M ^ n = μ₁ ^ n • (M - μ₂ • 1) - μ₂ ^ n • (M - μ₁ • 1)

