lemma exists_conj_mem {g : GL (Fin 2) ℝ} {A B A₁ B₁ : SL(2, ℝ)}
    (hA : g * toGL A * g⁻¹ = toGL A₁) (hB : g * toGL B * g⁻¹ = toGL B₁) {γ : SL(2, ℝ)}
    (hγ : γ ∈ Subgroup.closure {A, B}) :
