theorem ramificationIdx_punctured (c : ℂ) {q : Ideal (puncturedRing E)}
    (hq : q ∈ (RingHom.ker (aeval c : ℂ[X] →ₐ[ℂ] ℂ)).primesOver (puncturedRing E)) :
    q.ramificationIdx ℂ[X] = Uniformization.RatFuncPoly.mult (E₂ E) c

